class Solution {
 vector<long long> dijkstra(int s,const vector<vector<pair<int,int>>>& g){int n=g.size();const long long INF=LLONG_MAX/4;vector<long long>d(n,INF);priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>>pq;d[s]=0;pq.push({0,s});while(!pq.empty()){auto cur=pq.top();pq.pop();long long dist=cur.first;int u=cur.second;if(dist!=d[u])continue;for(auto e:g[u])if(dist+e.second<d[e.first]){d[e.first]=dist+e.second;pq.push({d[e.first],e.first});}}return d;}
 public: vector<bool> findAnswer(int n,vector<vector<int>>& edges){vector<vector<pair<int,int>>>g(n);for(auto&e:edges){g[e[0]].push_back({e[1],e[2]});g[e[1]].push_back({e[0],e[2]});}auto a=dijkstra(0,g),b=dijkstra(n-1,g);vector<bool>ans(edges.size());for(int i=0;i<(int)edges.size();++i){auto&e=edges[i];int u=e[0],v=e[1],w=e[2];ans[i]=(a[u]<LLONG_MAX/4&&a[u]+w+b[v]==a[n-1])||(a[v]<LLONG_MAX/4&&a[v]+w+b[u]==a[n-1]);}return ans;}
};
